"""External requirements generated by ``config/update-external.py``.

Do not edit this file directly. External project revisions come from their
``config/external/<name>/uv.lock`` files, the promoted GPU vLLM release comes
from ``config/external/vllm/gpu-release.toml``, the paired TPU wheel release
comes from ``config/external/vllm/tpu-release.toml``, and separate TPU fork
requirements come from ``config/external/vllm/tpu-forks.toml``.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class ExternalDependency:
    """An external distribution installed from an immutable Git revision."""

    config_name: str
    distribution: str
    repository: str
    version: str
    commit: str
    runtime_requirements: tuple[str, ...]

    def requirement(self, extras: tuple[str, ...] = ()) -> str:
        """Return a PEP 508 requirement for this revision."""
        distribution = self.distribution
        if extras:
            distribution = f"{distribution}[{','.join(extras)}]"
        return f"{distribution} @ git+{self.repository}@{self.commit}"


@dataclass(frozen=True)
class VllmGpuWheel:
    """One architecture-specific wheel from a promoted vLLM GPU release."""

    architecture: str
    sm_targets: tuple[str, ...]
    url: str
    sha256: str


@dataclass(frozen=True)
class VllmGpuRelease:
    """Immutable artifacts and ABI for a promoted vLLM GPU release."""

    release_tag: str
    source_commit: str
    version: str
    torch_backend: str
    wheels: tuple[VllmGpuWheel, ...]


@dataclass(frozen=True)
class VllmTpuWheel:
    """One wheel in the exact TPU serving pair."""

    distribution: str
    source_commit: str
    version: str
    url: str
    sha256: str


@dataclass(frozen=True)
class VllmTpuRelease:
    """Hash-pinned wheel pair and resolver boundary for TPU serving."""

    release_tag: str
    workflow_commit: str
    python_version: str
    exclude_newer: str
    vllm: VllmTpuWheel
    tpu_inference: VllmTpuWheel


